<?php
require_once __DIR__.'/auth.php';
require_once __DIR__.'/../workflow_support.php';
$filters=[];foreach(['status','priority','category','from','to','owner','overdue'] as $key)$filters[$key]=is_string($_GET[$key]??null)?trim($_GET[$key]):'';
$where=[];$params=[];$error='';
foreach(['status'=>['filed','acknowledged','processing','resolved'],'priority'=>['low','medium','high']] as $key=>$allowed){if($filters[$key]!==''){if(!in_array($filters[$key],$allowed,true))$error='Choose valid report filters.';else{$where[]="c.$key=?";$params[]=$filters[$key];}}}
if($filters['category']!==''){$where[]='c.complaint_type=?';$params[]=$filters['category'];}
if($filters['owner']!==''){if(!ctype_digit($filters['owner']))$error='Choose a valid staff member.';else{$where[]='c.assigned_staff_id=?';$params[]=(int)$filters['owner'];}}
foreach(['from','to'] as $key){if($filters[$key]==='')continue;if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$filters[$key])){$error='Enter valid date filters.';continue;}$date=DateTimeImmutable::createFromFormat('!Y-m-d',$filters[$key]);if(!$date||$date->format('Y-m-d')!==$filters[$key]){$error='Enter valid date filters.';continue;}$where[]=$key==='from'?'c.created_at>=?':'c.created_at<?';$params[]=$key==='from'?$date->format('Y-m-d'):$date->modify('+1 day')->format('Y-m-d');}
if($filters['from']!==''&&$filters['to']!==''&&$filters['from']>$filters['to'])$error='Start date must precede the end date.';
if($filters['overdue']==='1')$where[]="c.due_date<CURDATE() AND c.status<>'resolved'";
if($error){http_response_code(422);$where[]='1=0';}
$condition=$where?' WHERE '.implode(' AND ',$where):'';
$query=$pdo->prepare("SELECT c.*,u.full_name AS owner_name FROM complaints c LEFT JOIN users u ON u.id=c.assigned_staff_id $condition ORDER BY c.created_at DESC,c.id DESC");$query->execute($params);$reports=$query->fetchAll(PDO::FETCH_ASSOC);
$team=$pdo->query("SELECT id,full_name FROM users WHERE role IN ('admin','staff') ORDER BY full_name")->fetchAll(PDO::FETCH_ASSOC);
$categories=$pdo->query('SELECT DISTINCT complaint_type FROM complaints ORDER BY complaint_type')->fetchAll(PDO::FETCH_COLUMN);
$performance=$pdo->query("SELECT u.id,u.full_name,u.is_active,COUNT(c.id) AS assigned,SUM(c.status='resolved') AS resolved,SUM(c.status<>'resolved' AND c.due_date<CURDATE()) AS overdue,AVG(CASE WHEN c.resolved_at IS NOT NULL THEN TIMESTAMPDIFF(HOUR,c.created_at,c.resolved_at) END) AS resolution_hours,AVG(CASE WHEN c.acknowledged_at IS NOT NULL THEN TIMESTAMPDIFF(HOUR,c.created_at,c.acknowledged_at) END) AS response_hours FROM users u LEFT JOIN complaints c ON c.assigned_staff_id=u.id WHERE u.role IN ('admin','staff') GROUP BY u.id,u.full_name,u.is_active ORDER BY assigned DESC,u.full_name")->fetchAll(PDO::FETCH_ASSOC);
$hotspots=[];foreach($reports as $report){$key=trim(mb_strtolower($report['address']));if($key==='')continue;if(!isset($hotspots[$key]))$hotspots[$key]=['address'=>$report['address'],'count'=>0];$hotspots[$key]['count']++;}uasort($hotspots,fn($a,$b)=>$b['count']<=>$a['count']);
$overdue=count(array_filter($reports,fn($c)=>$c['status']!=='resolved'&&$c['due_date']&&$c['due_date']<date('Y-m-d')));
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operations — Barangay Mudiang</title><link rel="stylesheet" href="../assets/vendor/bootstrap.min.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><?php include __DIR__.'/../ui_theme.php'; ?></head><body class="portal-page resident-directory">
<?php include __DIR__.'/operations_nav.php'; ?>
<main class="main"><header class="topbar"><div class="topbar-left"><h1>Operations overview</h1><p>Ownership, deadlines and community patterns</p></div><button class="btn btn-outline" onclick="window.print()">Print report</button></header><div class="content">
<section class="dashboard-intro"><div><span class="portal-kicker">Community / Service performance</span><h2>Turn reports into measurable action.</h2><p>Explore concerns by location and keep overdue work visible.</p></div><span class="intro-tag"><?= count($reports) ?> matching reports · <?= $overdue ?> overdue</span></section>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= reportActivityEscape($error) ?></div><?php endif; ?>
<section class="card mb-4"><form method="get" class="card-body row g-3">
<?php foreach(['status'=>['filed','acknowledged','processing','resolved'],'priority'=>['low','medium','high'],'category'=>$categories] as $key=>$choices): ?><div class="col-md-4"><label class="form-label" for="filter-<?= $key ?>"><?= ucfirst($key) ?></label><select class="form-control" name="<?= $key ?>" id="filter-<?= $key ?>"><option value="">All</option><?php foreach($choices as $choice): ?><option value="<?= reportActivityEscape($choice) ?>" <?= $filters[$key]===$choice?'selected':'' ?>><?= reportActivityEscape(ucfirst($choice)) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
<div class="col-md-4"><label for="filter-owner" class="form-label">Assigned staff</label><select class="form-control" id="filter-owner" name="owner"><option value="">All staff</option><?php foreach($team as $person): ?><option value="<?= (int)$person['id'] ?>" <?= $filters['owner']===(string)$person['id']?'selected':'' ?>><?= reportActivityEscape($person['full_name']) ?></option><?php endforeach; ?></select></div>
<?php foreach(['from'=>'Reported from','to'=>'Reported through'] as $key=>$label): ?><div class="col-md-4"><label class="form-label" for="filter-<?= $key ?>"><?= $label ?></label><input class="form-control" type="date" id="filter-<?= $key ?>" name="<?= $key ?>" value="<?= reportActivityEscape($filters[$key]) ?>"></div><?php endforeach; ?>
<div class="col-12 d-flex align-items-center flex-wrap gap-3"><label><input type="checkbox" name="overdue" value="1" <?= $filters['overdue']==='1'?'checked':'' ?>> Overdue only</label><button class="btn btn-primary">Apply filters</button><a class="btn btn-outline" href="operations.php">Clear</a></div></form></section>
<section class="card mb-4"><div class="card-header"><h2>Complaint geography</h2></div><div class="card-body"><div id="operations-map" style="height:400px" aria-label="Map of filtered complaint locations"></div><p class="text-muted mt-3">Markers show the filtered reports. Larger markers indicate more reports at approximately the same coordinates.</p><div class="d-flex flex-wrap gap-3"><span>Filed: clay</span><span>Acknowledged: blue</span><span>Processing: brass</span><span>Resolved: green</span></div></div></section>
<section class="card mb-4"><div class="card-header"><h2>Reports needing attention</h2></div><div class="table-wrap"><table><thead><tr><th>Report</th><th>Owner</th><th>Status</th><th>Target completion</th><th>Resident confirmation</th></tr></thead><tbody><?php foreach($reports as $c): ?><tr><td><a href="edit_complaint.php?id=<?= (int)$c['id'] ?>">#<?= (int)$c['id'] ?> · <?= reportActivityEscape($c['complaint_type']) ?></a></td><td><?= reportActivityEscape($c['owner_name']?:'Unassigned') ?></td><td><?= ucfirst($c['status']) ?></td><td><?= reportActivityEscape($c['due_date']?:'Not scheduled') ?><?php if($c['due_date']&&$c['due_date']<date('Y-m-d')&&$c['status']!=='resolved'): ?> <strong class="text-danger">Overdue</strong><?php endif; ?></td><td><?= $c['resident_confirmed_at']?'Confirmed':($c['status']==='resolved'&&$c['user_id']?'Awaiting resident':'—') ?></td></tr><?php endforeach; ?><?php if(!$reports): ?><tr><td colspan="5">No reports match these filters.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card mb-4"><div class="card-header"><div><h2>Staff performance</h2><p>All-time totals by current assignee. Times include reports with recorded milestones.</p></div></div><div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Assigned</th><th>Resolved</th><th>Overdue</th><th>Average first acknowledgement</th><th>Average resolution</th></tr></thead><tbody><?php foreach($performance as $person): ?><tr><td><?= reportActivityEscape($person['full_name']) ?><?= $person['is_active']?'':' (inactive)' ?></td><td><?= (int)$person['assigned'] ?></td><td><?= (int)$person['resolved'] ?></td><td><?= (int)$person['overdue'] ?></td><td><?= $person['response_hours']!==null?number_format($person['response_hours'],1).' hours':'No recorded milestone' ?></td><td><?= $person['resolution_hours']!==null?number_format($person['resolution_hours'],1).' hours':'No recorded milestone' ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><div class="card-header"><div><h2>Repeated report locations</h2><p>Matching reports grouped by the same written address; these are indicators for review.</p></div></div><div class="card-body"><?php $repeated=false;foreach(array_slice($hotspots,0,10) as $hotspot): if($hotspot['count']<2)continue;$repeated=true; ?><p><strong><?= reportActivityEscape($hotspot['address']) ?></strong> · <?= $hotspot['count'] ?> reports</p><?php endforeach;if(!$repeated): ?><p>No repeated addresses in this selection.</p><?php endif; ?></div></section>
</div></main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const reports=<?= json_encode($reports,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
const map=L.map('operations-map').setView([7.182708,125.622193],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);
const colors={filed:'#a77853',acknowledged:'#59788c',processing:'#b08b3f',resolved:'#34755b'},counts={},bounds=[];
for(const c of reports){const k=Number(c.latitude).toFixed(3)+','+Number(c.longitude).toFixed(3);counts[k]=(counts[k]||0)+1;}
for(const c of reports){const lat=Number(c.latitude),lng=Number(c.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lng))continue;const point=[lat,lng],k=lat.toFixed(3)+','+lng.toFixed(3);bounds.push(point);const popup=document.createElement('div'),title=document.createElement('strong'),details=document.createElement('p'),link=document.createElement('a');title.textContent='#'+c.id+' · '+c.complaint_type;details.textContent=c.address+' · '+c.status;link.textContent='Review report';link.href='edit_complaint.php?id='+Number(c.id);popup.append(title,details,link);L.circleMarker(point,{radius:Math.min(20,7+counts[k]*2),color:colors[c.status],fillOpacity:.65}).addTo(map).bindPopup(popup);}
if(bounds.length)map.fitBounds(bounds,{padding:[30,30],maxZoom:16});
</script><?php include __DIR__.'/notification_widget.php'; ?></body></html>
